window.AUTH=window.AUTH||{};window.AUTH["20-1650"]={"d":"20-1650","id":"2021/20-1650","n":"Concepcion v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Carlos Concepcion","date":"2021-11-15","url":"https://www.supremecourt.gov/DocketPDF/20/20-1650/199878/20211115105840761_Concepcion%20-%20Brief%20for%20Petitioner%20-%20to%20file.pdf","side":"pet","n":68},{"k":"respondent","label":"Brief of respondent United States","date":"2021-12-15","url":"https://www.supremecourt.gov/DocketPDF/20/20-1650/205216/20211215144620166_20-1650bsUnitedStates.pdf","side":"res","n":94},{"k":"reply","label":"Reply of petitioner Carlos Concepcion","date":"2022-01-07","url":"https://www.supremecourt.gov/DocketPDF/20/20-1650/207683/20220107142644921_Concepcion%20Reply%20Brief.pdf","side":"pet","n":52}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/597us2r61_7khn.pdf","tr":true,"items":[{"t":"case","label":"Beazer v. United States","cite":"360 F. Supp. 3d 1","y":2019,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/360/1/","by":{"0":"11"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"sum":"The Court found that international treaties cannot overstep state sovereignty, and enforcement should be limited to international affairs.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Danforth v. Minnesota","cite":"552 U.S. 264","y":2008,"id":"2007/06-8273","sc":1,"op":1,"sum":"The Court held that the federal case law precedent, including Teague did not constrain the authority of state courts to give broader effect to new rules of criminal procedure than was required by the precedent. The precedent applied only to federal habeas corpus petitions and had no bearing on state post-conviction proceedings.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Dean v. United States","cite":"556 U.S. 568","y":2009,"id":"2008/08-5274","sc":1,"sum":"The Court held that 18 U.S.C. Section 924(c)(1)(A)(iii) does not require proof of intent to discharge a firearm in order to enhance a sentence.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Dillon v. United States","cite":"560 U.S. 817","y":2010,"id":"2009/09-6338","sc":1,"op":1,"ar":3,"sum":"The Court held that federal sentencing guidelines are binding when a district court imposes a new sentence under a revised guideline range.","sumSrc":"Oyez","by":{"0":"16, 35, 43, 44","1":"passim","2":"17, 18, 19"}},{"t":"case","label":"Dorsey v. United States","cite":"567 U.S. 260","y":2012,"id":"2011/11-5683","sc":1,"ar":1,"sum":"The Court held that criminals who had committed drug crimes before the passage of the Fair Sentencing Act of 2010 but were sentenced after its passage were entitled to the sentencing provisions laid out in the Act.","sumSrc":"Oyez","by":{"0":"passim","1":"6, 7, 8, 29, 35"}},{"t":"case","label":"Gall v. United States","cite":"552 U.S. 38","y":2007,"id":"2007/06-7949","sc":1,"op":2,"ar":3,"sum":"The Supreme Court, in a 7-2 ruling, reversed the appellate court and held that, under Booker , federal courts have the authority to set any reasonable sentence as long as they explain their reasoning. The Court made clear that Booker had removed the Guidelines from their earlier status as the primary determinate of a defendant's punishment, reaffirming the Guidelines' advisory status.","sumSrc":"Oyez","by":{"0":"19, 21, 30","1":"35, 42","2":"8, 12"}},{"t":"case","label":"Harper v. Va. Dep’t of Tax’n","cite":"509 U.S. 86","y":1993,"id":"1992/91-794","sc":1,"sum":"In Davis v. Michigan Dept. of Treasury,489 U. S. 803, this Court invalidated Michigan's practice of taxing retirement benefits paid by the Federal Government while exempting retirement benefits paid by the State or its political subdivisions. Because Michigan conceded that a refund to federal retirees was the appropriate remedy, the Court remanded for entry of judgment against the State. Virginia subsequently …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33, 42, 43"}},{"t":"case","label":"Hillman v. Maretta","cite":"569 U.S. 483","y":2013,"id":"2012/11-1221","sc":1,"sum":"The Court found that the Federal Employees' Group Life Insurance Act preempts a Virginia state law regarding beneficiary designation upon divorce.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Holguin-Hernandez v. United States","cite":"140 S. Ct. 762","y":2020,"id":"2019/18-7739","sc":1,"sum":"The Court held that a criminal defendant's district-court argument for a specific sentence preserved his claim on appeal that the sentence imposed was unreasonably long.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"James B. Beam Distilling Co. v. Georgia","cite":"501 U.S. 529","y":1991,"id":"1990/89-680","sc":1,"sum":"The judgment is reversed, and the case is remanded. 259 Ga. 363, 382 S. E. 2d 95, reversed and remanded. JUSTICE SOUTER, joined by JUSTICE STEVENS, concluded that once this Court has applied a rule of law to the litigants in one case, it must do so with respect to all others not barred by procedural requirements or res judicata.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33, 42","2":"16"}},{"t":"case","label":"Johnson v. United States","cite":"576 U.S. 591","y":2015,"id":"2014/13-7120","sc":1,"op":1,"sum":"The Court determined that the residual clause of the Armed Criminal Career Act is unconstitutionally vague.","sumSrc":"Oyez","by":{"0":"11"}},{"t":"case","label":"Kelley v. United States","cite":"962 F.3d 470","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/962/470/","op":1,"ar":1,"by":{"0":"22","1":"24, 27, 38","2":"21"}},{"t":"case","label":"Kimbrough v. United States","cite":"552 U.S. 85","y":2007,"id":"2007/06-6330","sc":1,"op":3,"sum":"Justice Ruth Bader Ginsburg authored the Court's 7-2 majority opinion reversing the Fourth Circuit and affirming the sentence handed down by the trial judge. Ginsburg noted that the drug trafficking statute still had some minimum sentencing requirements, and expressed the Court's confidence that district courts could maintain reasonably uniform approaches to cocaine sentencing.","sumSrc":"Oyez","by":{"0":"33","1":"4, 5, 6"}},{"t":"case","label":"Koon v. United States","cite":"518 U.S. 81","y":1996,"id":"1995/94-1664","sc":1,"op":3,"sum":"The Court held that the Court of Appeals should not review de novo a decision to depart from the Guideline sentencing range, but instead should ask whether the sentencing court abused its discretion.","sumSrc":"Oyez","by":{"0":"45","2":"8, 13, 20"}},{"t":"case","label":"Merck & Co. v. Reynolds","cite":"559 U.S. 633","y":2010,"id":"2009/08-905","sc":1,"sum":"The Court held that a statute of limitations begins to run once a plaintiff actually discovers -- or a reasonably diligent plaintiff would have discovered -- the facts constituting the violation in the present case, whichever comes first.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Molina-Martinez v. United States","cite":"136 S. Ct. 1338","y":2016,"id":"2015/14-8913","sc":1,"sum":"The Court held that an error in the application of the U.S. Sentencing Guidelines that results in the wrong Guideline range affected the defendant’s substantial rights.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Pepper v. United States","cite":"562 U.S. 476","y":2011,"id":"2010/09-6822","sc":1,"op":7,"ar":5,"sum":"The Court held that when a defendant's sentence has been set aside on appeal, a district court may consider evidence of the defendant's rehabilitation after the initial sentences, which may support lesser sentencing guidelines.","sumSrc":"Oyez","by":{"0":"passim","1":"32, 35","2":"6, 14, 15"}},{"t":"case","label":"Pereira v. Sessions","cite":"138 S. Ct. 2105","y":2018,"id":"2017/17-459","sc":1,"sum":"The Court held that a notice to appear for a removal hearing that does not specify the place and time of the hearing does not trigger the stop-time rule of 8 U.S.C. § 1229b(b)(1), which gives the attorney general discretion to cancel removal for an alien who, among other criteria, has been continuously physically present in the country for at least ten years.","sumSrc":"Oyez","by":{"0":"20","2":"4"}},{"t":"case","label":"Peugh v. United States","cite":"569 U.S. 530","y":2013,"id":"2012/12-62","sc":1,"op":1,"sum":"The Court found that using the U.S. Sentencing Guidelines at the time of the sentencing for a crime rather than at the time of the offense is a violation of the ex post facto clause.","sumSrc":"Oyez","by":{"0":"30, 31","1":"35"}},{"t":"case","label":"Plaut v. Spendthrift Farm, Inc.","cite":"514 U.S. 211","y":1995,"id":"1994/93-1121","sc":1,"sum":"The Court concluded that Congress had usurped power assigned to the judiciary by Article III and thus had violated the separation of powers principle.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Powerex Corp. v. Reliant Energy Servs.","cite":"551 U.S. 224","y":2007,"id":"2006/05-85","sc":1,"op":1,"sum":"The Court ruled 7-2 that the Ninth Circuit lacked jurisdiction to review the District Court's remand order. The Court relied on 28 U.S.C. 1447(d), which precludes appellate review of remands based on lack of subject-matter jurisdiction.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Rita v. United States","cite":"551 U.S. 338","y":2007,"id":"2006/06-5754","sc":1,"op":2,"ar":2,"sum":"The Court ruled that courts of appeals may apply a nonbinding presumption of reasonableness to within-Guidelines sentences. Justice Stephen Breyer wrote the opinion for the 8-1 majority.","sumSrc":"Oyez","by":{"0":"19, 46","2":"12, 22"}},{"t":"case","label":"Ryan v. Gonzales","cite":"568 U.S. 57","y":2013,"id":"2012/10-930","sc":1,"sum":"The Court held that no right to competence exists during federal habeas corpus proceedings.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Shapiro v. McManus","cite":"136 S. Ct. 450","y":2015,"id":"2015/14-990","sc":1,"sum":"The Court held that a claim covered by the Three-Judge Court Act must be heard by a three-judge panel.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Tanzin v. Tanvir","cite":"141 S. Ct. 486","y":2020,"id":"2020/19-71","sc":1,"sum":"The Religious Freedom Restoration Act of 1993’s express remedies provision, see 42 U. S. C. §2000bb–1(c), permits litigants, when appropriate, to obtain money damages against federal officials in their individual capacities.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"18"}},{"t":"case","label":"Taylor v. United States","cite":"495 U.S. 575","y":1990,"id":"1989/88-7194","sc":1,"sum":"An offense constitutes \"burglary\" under §924(e) if, regardless of its exact definition or label, it has the basic elements of a \"generic\" burglary-i. e., an unlawful or unprivileged entry into, or remaining in, a building or other structure, with intent to commit a crime-or if the charging paper and jury instructions actually required the jury to find all the elements of generic burglary in order to convict the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34","2":"19"}},{"t":"case","label":"Terry v. United States","cite":"141 S. Ct. 1858","y":2021,"id":"2020/20-5904","sc":1,"sum":"A sentence reduction under the First Step Act is available only if an offender’s prior conviction of a crack cocaine offense triggered a mandatory minimum sentence.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"passim","1":"8, 29","2":"14"}},{"t":"case","label":"United States v. Adams","cite":"746 F.3d 734","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/746/734/","by":{"0":"32"}},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"sum":"It is not clear from the language and legislative history of § 1202 (a) (1) whether or not receipt or possession of a firearm by a convicted felon has to be shown in an individual prosecution to have been connected with interstate commerce. The ambiguity of this provision (which is not only a criminal statute but one whose broad construction would define as a federal offense conduct readily proscribed by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34","1":"36"}},{"t":"case","label":"United States v. Booker","cite":"543 U.S. 220","y":2005,"id":"2004/04-104","sc":1,"ar":1,"sum":"The Court held that the Sentencing Guidelines, where they allow judges to enhance sentences using facts not reviewed by juries, violated the Sixth Amendment right to trial by jury. The sentences of Booker and Fanfan, based partly on facts determined only by judges, were therefore unconstitutional.","sumSrc":"Oyez","by":{"0":"27","1":"40","2":"15, 18"}},{"t":"case","label":"United States v. Brown","cite":"974 F.3d 1137","y":2020,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/974/1137/","op":1,"by":{"0":"43","1":"24, 37, 38"}},{"t":"case","label":"United States v. Bryson","cite":"229 F.3d 425","y":2000,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/229/425/","by":{"0":"20"}},{"t":"case","label":"United States v. Campbell","cite":"168 F.3d 263","y":1999,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/168/263/","by":{"0":"31"}},{"t":"case","label":"United States v. Caraballo","cite":"552 F.3d 6","y":2008,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/552/6/","by":{"0":"8"}},{"t":"case","label":"United States v. Chambers","cite":"956 F.3d 667","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/956/667/","by":{"0":"43","1":"30, 38, 39","2":"15"}},{"t":"case","label":"United States v. Collington","cite":"995 F.3d 347","y":2021,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/995/347/","op":1,"by":{"0":"23, 26, 44"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"34"}},{"t":"case","label":"United States v. Denson","cite":"963 F.3d 1080","y":2020,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/963/1080/","op":1,"by":{"0":"39","1":"24, 34","2":"19"}},{"t":"case","label":"United States v. Easter","cite":"975 F.3d 318","y":2020,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/975/318/","op":1,"by":{"0":"19, 29","1":"24","2":"11, 13"}},{"t":"case","label":"United States v. Fluker","cite":"891 F.3d 541","y":2018,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/891/541/","by":{"0":"32"}},{"t":"case","label":"United States v. Garcia-Ortiz","cite":"904 F.3d 102","y":2018,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/904/102/","by":{"0":"32"}},{"t":"case","label":"United States v. Gee","cite":"843 F. App’x 215","y":2021,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/843/215/","by":{"0":"39"}},{"t":"case","label":"United States v. Granderson","cite":"511 U.S. 39","y":1994,"id":"1993/92-1662","sc":1,"sum":"The Court held 7-2 that the U.S. Code's section 3565 refers to the original sentence range set by U.S. Sentencing Guidelines. Therefore, the minimum revocation sentence for drug possession while on probation is one third the maximum of the Guidelines range of imprisonment; the maximum revocation sentence is the Guidelines maximum.","sumSrc":"Oyez","by":{"0":"33","2":"19"}},{"t":"case","label":"United States v. Handa","cite":"122 F.3d 690","y":1997,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/122/690/","by":{"0":"32"}},{"t":"case","label":"United States v. Harris","cite":"960 F.3d 1103","y":2020,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/960/1103/","op":1,"by":{"0":"39","2":"13"}},{"t":"case","label":"United States v. Hegwood","cite":"934 F.3d 414","y":2019,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/934/414/","op":2,"by":{"0":"38","1":"24, 27","2":"21"}},{"t":"case","label":"United States v. Hogan","cite":"722 F.3d 55","y":2013,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/722/55/","by":{"0":"8"}},{"t":"case","label":"United States v. Hunter","cite":"809 F.3d 677","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/809/677/","by":{"0":"32"}},{"t":"case","label":"United States v. Kennedy","cite":"881 F.3d 14","y":2018,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/881/14/","by":{"0":"11"}},{"t":"case","label":"United States v. Moyhernandez","cite":"5 F.4th 195","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/5/195/","sum":"Observing that the Section 3553(a) factors “may often prove useful” in Section 404 proceedings.","sumSrc":"brief:1","by":{"0":"27","1":"41, 42"}},{"t":"case","label":"United States v. Murphy","cite":"998 F.3d 549","y":2021,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/998/549/","by":{"0":"21, 43","2":"12"}},{"t":"case","label":"United States v. Phillips","cite":"797 F. App’x 516","y":2020,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/797/516/","by":{"0":"39"}},{"t":"case","label":"United States v. Shaw","cite":"957 F.3d 734","y":2020,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/957/734/","op":1,"by":{"0":"29","1":"41","2":"13"}},{"t":"case","label":"United States v. Smith","cite":"756 F.3d 1179","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/756/1179/","by":{"0":"30","1":"35"}},{"t":"case","label":"United States v. Starks","cite":"861 F.3d 306","y":2017,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/861/306/","by":{"0":"11"}},{"t":"case","label":"United States v. Steward","cite":"598 F.3d 960","y":2010,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/598/960/","by":{"0":"31"}},{"t":"case","label":"United States v. Sutton","cite":"962 F.3d 979","y":2020,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/962/979/","by":{"0":"39"}},{"t":"case","label":"United States v. Triestman","cite":"178 F.3d 624","y":1999,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/178/624/","op":1,"by":{"0":"44","2":"17"}},{"t":"case","label":"United States v. Waite","cite":"12 F.4th 204","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/12/204/","by":{"0":"22"}},{"t":"case","label":"United States v. West","cite":"646 F.3d 745","y":2011,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/646/745/","by":{"0":"31"}},{"t":"usc","label":"1 U.S.C. § 109","url":"https://www.law.cornell.edu/uscode/text/1/109","stext":{"head":"§109. Repeal of statutes as affecting existing liabilities","paras":[[0,"The repeal of any statute shall not have the effect to release or extinguish any penalty, forfeiture, or liability incurred under such statute, unless the repealing Act shall so expressly provide, and such statute shall be treated as still remaining in force for the purpose of sustaining any proper action or prosecution for the enforcement of such penalty, forfeiture, or liability. The expiration of a temporary statute shall not have the effect to release or extinguish any penalty, forfeiture, or liability incurred under such statute, unless the temporary statute shall so expressly provide, and such statute shall be treated as still remaining in force for the purpose of sustaining any proper action or prosecution for the enforcement of such penalty, forfeiture, or liability."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/1/109?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§109. Repeal of statutes as affecting existing liabilities","tname":"General Provisions","by":{"0":"passim","1":"29, 35","2":"8"}},{"t":"usc","label":"18 U.S.C. § 3551","url":"https://www.law.cornell.edu/uscode/text/18/3551","stext":{"head":"§3551. Authorized sentences","paras":[[0,"(a) In General.—Except as otherwise specifically provided, a defendant who has been found guilty of an offense described in any Federal statute, including sections 13 and 1153 of this title, other than an Act of Congress applicable exclusively in the District of Columbia or the Uniform Code of Military Justice, shall be sentenced in accordance with the provisions of this chapter so as to achieve the purposes set forth in subparagraphs (A) through (D) of section 3553(a)(2) to the extent that they are applicable in light of all the circumstances of the case."],[0,"(b) Individuals.—An individual found guilty of an offense shall be sentenced, in accordance with the provisions of section 3553, to—"],[1,"(1) a term of probation as authorized by subchapter B;"],[1,"(2) a fine as authorized by subchapter C; or"],[1,"(3) a term of imprisonment as authorized by subchapter D."],[0,"A sentence to pay a fine may be imposed in addition to any other sentence. A sanction authorized by section 3554, 3555, or 3556 may be imposed in addition to the sentence required by this subsection."],[0,"(c) Organizations.—An organization found guilty of an offense shall be sentenced, in accordance with the provisions of section 3553, to—"],[1,"(1) a term of probation as authorized by subchapter B; or"],[1,"(2) a fine as authorized by subchapter C."],[0,"A sentence to pay a fine may be imposed in addition to a sentence to probation. A sanction authorized by section 3554, 3555, or 3556 may be imposed in addition to the sentence required by this subsection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3551?type=usc&year=mostrecent&link-type=html"},"head":"§3551. Authorized sentences","tname":"Crimes and Criminal Procedure","by":{"0":"13, 18","1":"33","2":"3"}},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","subs":["(a)(2006)","(a)","(a)(1)(2006)","(a)(1)","(b)","(b)(1)(A)","(b)(1)(A)(i)","(b)(1)(A)(ii)","(b)(1)(A)(iii)","(b)(1)(B)(2006)","(b)(1)(B)","(b)(1)(B)(i)","(b)(1)(B)(ii)","(b)(1)(B)(iii)(2006)","(b)(1)(B)(iii)","(b)(1)(C)"],"stext":{"head":"§841. Prohibited acts A","paras":[[0,"(a) Unlawful acts"],[0,"Except as authorized by this subchapter, it shall be unlawful for any person knowingly or intentionally—"],[1,"(1) to manufacture, distribute, or dispense, or possess with intent to manufacture, distribute, or dispense, a controlled substance; or"],[1,"(2) to create, distribute, or dispense, or possess with intent to distribute or dispense, a counterfeit substance."],[0,"(b) Penalties"],[0,"Except as otherwise provided in section 849, 859, 860, or 861 of this title, any person who violates subsection (a) of this section shall be sentenced as follows:"],[0,"(1)(A) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 1 kilogram or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 5 kilograms or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 280 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 100 grams or more of phencyclidine (PCP) or 1 kilogram or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 10 grams or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 400 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 100 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 1000 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 1,000 or more marihuana plants regardless of weight; or"],[1,"(viii) 50 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 500 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 10 years or more than life and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $10,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment of not less than 15 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $20,000,000 if the defendant is an individual or $75,000,000 if the defendant is other than an individual, or both. If any person commits a violation of this subparagraph or of section 849, 859, 860, or 861 of this title after 2 or more prior convictions for a serious drug felony or serious violent felony have become final, such person shall be sentenced to a term of imprisonment of not less than 25 years and fined in accordance with the preceding sentence. Notwithstanding section 3583 of title 18, any sentence under this subparagraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 5 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 10 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(B) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 100 grams or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 500 grams or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 28 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 10 grams or more of phencyclidine (PCP) or 100 grams or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 1 gram or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 40 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 10 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 100 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 100 or more marihuana plants regardless of weight; or"],[1,"(viii) 5 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 50 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 5 years and not more than 40 years and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $5,000,000 if the defendant is an individual or $25,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment which may not be less than 10 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $8,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposed under this subparagraph shall, in the absence of such a prior conviction, include a term of supervised release of at least 4 years in addition to such term of imprisonment and shall, if there was such a prior conviction, include a term of supervised release of at least 8 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(C) In the case of a controlled substance in schedule I or II, gamma hydroxybutyric acid (including when scheduled as an approved drug product for purposes of section 3(a)(1)(B) of the Hillory J. Farias and Samantha Reid Date-Rape Drug Prohibition Act of 2000), or 1 gram of flunitrazepam, except as provided in subparagraphs (A), (B), and (D), such person shall be sentenced to a term of imprisonment of not more than 20 years and if death or serious bodily injury results from the use of such substance shall be sentenced to a term of imprisonment of not less than twenty years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $1,000,000 if the defendant is an individual or $5,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a felony drug offense has become final, such person shall be sentenced to a term of imprisonment of not more than 30 years and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $2,000,000 if the defendant is an individual or $10,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposing a term of imprisonment under this paragraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 3 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 6 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under the provisions of this subparagraph which provide for a mandatory term of imprisonment if death or serious bodily injury results, nor shall a person so sentenced be eligible for parole during the term of such a sentence."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/841?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§841. Prohibited acts A","tname":"Food and Drugs","by":{"0":"passim","1":"6, 42, 4, 3, 10, 4, 4, 4, 5, 7, 4, 5, 7, 3, 10, 4, 5, 7, 12, 5, 5, 10, 42, 7, 12, 43"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"1"}},{"t":"law","label":"Pub. L. No. 99-570","url":"https://www.govinfo.gov/link/statute/100/3207","by":{"0":"6"}},{"t":"law","label":"Pub. L. No. 111-220","url":"https://www.govinfo.gov/link/plaw/111/public/220","by":{"0":"passim","2":"passim"}},{"t":"law","label":"Pub. L. No. 115-391","url":"https://www.govinfo.gov/link/plaw/115/public/391","by":{"0":"passim","2":"passim"}},{"t":"case","label":"Apprendi v. New Jersey","cite":"530 U.S. 466","y":2000,"id":"1999/99-478","sc":1,"sum":"The Court held that the Due Process Clause requires that any fact that increases the penalty for a crime beyond the prescribed statutory maximum, other than the fact of a prior conviction, must be submitted to a jury and proved beyond a reasonable doubt.","sumSrc":"Oyez","by":{"1":"40","2":"15"}},{"t":"case","label":"Bifulco v. United States","cite":"447 U.S. 381","y":1980,"id":"1979/79-5010","sc":1,"sum":"Section 406 of the Act does not authorize the imposition of a special parole term even though that sanction is included within the penalty provision of the target offense.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"36","2":"18"}},{"t":"case","label":"Camreta v. Greene","cite":"563 U.S. 692","y":2011,"id":"2010/09-1454","sc":1,"sum":"A case which the Court vacated in part and remanded in favor of the defendant without addressing the Fourth Amendment question at issue.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Chavez-Meza v. United States","cite":"138 S. Ct. 1959","y":2018,"id":"2017/17-5639","sc":1,"op":1,"sum":"The Court held that because the record in this case as a whole demonstrated that the judge had a reasoned basis for his decision, the judge’s explanation for reducing Adaucto Chavez-Meza’s sentence under 18 U.S.C. § 3582(c)(2) to the middle instead of the bottom of the amended Federal Guidelines range was adequate.","sumSrc":"Oyez","by":{"1":"33, 35"}},{"t":"case","label":"Christensen v. Harris Cnty.","cite":"529 U.S. 576","y":2000,"id":"1999/98-1167","sc":1,"sum":"The Court held 6-3 that \"[n]othing in the FLSA or its implementing regulations prohibits a public employer from compelling the use of compensatory time.\" Justice Thomas wrote for the Court that, \"under the FLSA, an employer is free to require an employee to take time off work, and an employer is also free to use the money it would have paid in wages to cash out accrued compensatory time.","sumSrc":"Oyez","by":{"1":"27, 28"}},{"t":"case","label":"Dean v. United States","cite":"137 S. Ct. 1170","y":2017,"id":"2016/15-9260","sc":1,"sum":"The Court determined that 18 U.S.C. §924(c) does not prevent a sentencing court from using its discretion to consider the other mandatory minimum sentences a defendant might be facing when calculating an overall appropriate sentence.","sumSrc":"Oyez","by":{"1":"32","2":"5"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Halo Elecs., Inc. v. Pulse Elecs., Inc.","cite":"579 U.S. 93","y":2016,"id":"2015/14-1513","sc":1,"sum":"The Court determined that the rigid two-part test is not necessary for determining whether a patentee is eligible for enhanced damages under 35 U.S.C §284.","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"King v. St. Vincent’s Hosp.","cite":"502 U.S. 215","y":1991,"id":"1991/90-889","sc":1,"sum":"Section 2024(d) does not limit the length of military service after which a member of the Armed Forces retains a right to civilian reemployment. Subsection (d)'s text-which specifies that any covered employee \"shall... be granted a leave... for the period required to perform active duty [and] [u]pon... release from... such duty... shall be permitted to return to [his or her] position\"-is utterly silent about any …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"Kingdomware Techs., Inc. v. United States","cite":"579 U.S. 162","y":2016,"id":"2015/14-916","sc":1,"sum":"The Court determined that the Court had jurisdiction to address the merits of the case even if the contracts had already been performed, and the Department of Veterans Affairs’ “set-aside” for veteran-owned businesses is mandatory.","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24, 33"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"sum":"The Court held that a discovery rule does not govern section 1681p of FCRA, as that section explicitly delineated the exceptional case in which discovery triggered the two-year limitation and Adelaide's case does not fall within the exceptional category. The Court reasoned that it was not at liberty to make Congress' explicit exception the general rule.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Teague v. Lane","cite":"489 U.S. 288","y":1989,"id":"1988/87-5259","sc":1,"sum":"The judgment is affirmed. 820 F. 2d 832, affirmed. JUSTICE O'CONNOR delivered the opinion of the Court with respect to Parts I, II, and III, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"United States v. Addonizio","cite":"442 U.S. 178","y":1979,"id":"1978/78-156","sc":1,"sum":"A federal prisoner's allegation that a postsentencing change in the policies of the United States Parole Commission has prolonged his actual imprisonment beyond the period intended by the sentencing judge will not support a collateral attack on the original sentence under 28 U. S. C. § 2255.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"United States v. Allen","cite":"956 F.3d 355","y":2020,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/956/355/","by":{"1":"41","2":"12"}},{"t":"case","label":"United States v. Blake","cite":"986 F.3d 756","y":2021,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/986/756/","by":{"1":"34"}},{"t":"case","label":"United States v. Brewer","cite":"836 Fed. Appx. 468","y":2021,"court":"8th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./836/468/","by":{"1":"24"}},{"t":"case","label":"United States v. Castleman","cite":"572 U.S. 157","y":2014,"id":"2013/12-1371","sc":1,"sum":"The Court held that a Tennessee man's conviction of domestic violence under state law also prevented him from legally possessing firearms under federal law.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"United States v. Foote","cite":"784 F.3d 931","y":2015,"url":"https://www.courtlistener.com/c/F.3d/784/931/","sum":"Rejecting availability of Section 2255 relief on the basis of a career-offender status invalidated by intervening case law.","sumSrc":"brief:1","by":{"1":"38"}},{"t":"case","label":"United States v. Foreman","cite":"958 F.3d 506","y":2020,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/958/506/","by":{"1":"31"}},{"t":"case","label":"United States v. Fowowe","cite":"1 F.4th 522","y":2021,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/1/522/","by":{"1":"27"}},{"t":"case","label":"United States v. Frady","cite":"456 U.S. 152","y":1982,"id":"1981/80-1595","sc":1,"op":1,"sum":"In 1963, respondent was convicted of first-degree murder and sentenced to death by a jury in the Federal District Court for the District of Columbia, which at that time had exclusive jurisdiction over local felonies committed in the District. The Court of Appeals for the District of Columbia Circuit, which then acted as the local appellate court, upheld the conviction but set aside the death sentence, and respondent …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"United States v. Harris","cite":"568 F.3d 666","y":2009,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/568/666/","by":{"1":"25"}},{"t":"case","label":"United States v. Hudson","cite":"967 F.3d 605","y":2020,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/967/605/","by":{"1":"32, 41","2":"4"}},{"t":"case","label":"United States v. Lancaster","cite":"997 F.3d 171","y":2021,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/997/171/","op":1,"by":{"1":"38","2":"7"}},{"t":"case","label":"United States v. Lawrence","cite":"1 F.4th 40","y":2020,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/1/40/","by":{"1":"34","2":"7"}},{"t":"case","label":"United States v. Mannie","cite":"971 F.3d 1145","y":2020,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/971/1145/","by":{"1":"41"}},{"t":"case","label":"United States v. Maxwell","cite":"991 F.3d 685","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/991/685/","op":3,"by":{"1":"26"}},{"t":"case","label":"United States v. Moore","cite":"975 F.3d 84","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/975/84/","op":1,"by":{"1":"24, 25, 27"}},{"t":"case","label":"United States v. Ron Pair Enters., Inc.","cite":"489 U.S. 235","y":1989,"id":"1988/87-1043","sc":1,"sum":"Section 506(b) entitles a creditor to receive postpetition interest on a nonconsensual oversecured claim allowed in a bankruptcy proceeding.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"United States v. Smith","cite":"958 F.3d 494","y":2020,"url":"https://www.courtlistener.com/c/F.3d/958/494/","by":{"1":"24"}},{"t":"case","label":"United States v. Wirsing","cite":"943 F.3d 175","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/943/175/","by":{"1":"24"}},{"t":"law","label":"Pub. L. No. 99-579","url":"https://www.govinfo.gov/link/statute/100/3207","by":{"1":"4"}},{"t":"usc","label":"21 U.S.C. § 801","url":"https://www.law.cornell.edu/uscode/text/21/801","by":{"1":"4"}},{"t":"usc","label":"21 U.S.C. § 812","url":"https://www.law.cornell.edu/uscode/text/21/812","by":{"1":"4"}},{"t":"usc","label":"21 U.S.C. § 851","url":"https://www.law.cornell.edu/uscode/text/21/851","by":{"1":"10"}},{"t":"usc","label":"21 U.S.C. § 960","url":"https://www.law.cornell.edu/uscode/text/21/960","subs":["(b)","(b)(1)","(b)(2)"],"by":{"1":"7, 5, 5"}},{"t":"usc","label":"18 U.S.C. § 3552","url":"https://www.law.cornell.edu/uscode/text/18/3552","subs":["(a)"],"by":{"1":"33"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(a)","(a)(1)","(a)(2)","(a)(4)","(c)"],"by":{"1":"29, 35, 29, 35, 29, 35, 29, 35, 29, 35, 29, 35"}},{"t":"usc","label":"18 U.S.C. § 3582","url":"https://www.law.cornell.edu/uscode/text/18/3582","subs":["(a)","(c)","(c)(1)(A)","(c)(1)(B)","(c)(2)"],"stext":{"head":"§3582. Imposition of a sentence of imprisonment","paras":[[0,"(a) Factors To Be Considered in Imposing a Term of Imprisonment.—The court, in determining whether to impose a term of imprisonment, and, if a term of imprisonment is to be imposed, in determining the length of the term, shall consider the factors set forth in section 3553(a) to the extent that they are applicable, recognizing that imprisonment is not an appropriate means of promoting correction and rehabilitation. In determining whether to make a recommendation concerning the type of prison facility appropriate for the defendant, the court shall consider any pertinent policy statements issued by the Sentencing Commission pursuant to 28 U.S.C. 994(a)(2)."],[0,"(b) Effect of Finality of Judgment.—Notwithstanding the fact that a sentence to imprisonment can subsequently be—"],[1,"(1) modified pursuant to the provisions of subsection (c);"],[1,"(2) corrected pursuant to the provisions of rule 35 of the Federal Rules of Criminal Procedure and section 3742; or"],[1,"(3) appealed and modified, if outside the guideline range, pursuant to the provisions of section 3742;"],[0,"a judgment of conviction that includes such a sentence constitutes a final judgment for all other purposes."],[0,"(c) Modification of an Imposed Term of Imprisonment.—The court may not modify a term of imprisonment once it has been imposed except that—"],[1,"(1) in any case—"],[2,"(A) the court, upon motion of the Director of the Bureau of Prisons, or upon motion of the defendant after the defendant has fully exhausted all administrative rights to appeal a failure of the Bureau of Prisons to bring a motion on the defendant's behalf or the lapse of 30 days from the receipt of such a request by the warden of the defendant's facility, whichever is earlier, may reduce the term of imprisonment (and may impose a term of probation or supervised release with or without conditions that does not exceed the unserved portion of the original term of imprisonment), after considering the factors set forth in section 3553(a) to the extent that they are applicable, if it finds that—"],[3,"(i) extraordinary and compelling reasons warrant such a reduction; or"],[3,"(ii) the defendant is at least 70 years of age, has served at least 30 years in prison, pursuant to a sentence imposed under section 3559(c), for the offense or offenses for which the defendant is currently imprisoned, and a determination has been made by the Director of the Bureau of Prisons that the defendant is not a danger to the safety of any other person or the community, as provided under section 3142(g);"],[2,"and that such a reduction is consistent with applicable policy statements issued by the Sentencing Commission; and"],[2,"(B) the court may modify an imposed term of imprisonment to the extent otherwise expressly permitted by statute or by Rule 35 of the Federal Rules of Criminal Procedure; and"],[1,"(2) in the case of a defendant who has been sentenced to a term of imprisonment based on a sentencing range that has subsequently been lowered by the Sentencing Commission pursuant to 28 U.S.C. 994(o), upon motion of the defendant or the Director of the Bureau of Prisons, or on its own motion, the court may reduce the term of imprisonment, after considering the factors set forth in section 3553(a) to the extent that they are applicable, if such a reduction is consistent with applicable policy statements issued by the Sentencing Commission."],[0,"(d) Notification Requirements.—"],[1,"(1) Terminal illness defined.—In this subsection, the term \"terminal illness\" means a disease or condition with an end-of-life trajectory."],[1,"(2) Notification.—The Bureau of Prisons shall, subject to any applicable confidentiality requirements—"],[2,"(A) in the case of a defendant diagnosed with a terminal illness—"],[3,"(i) not later than 72 hours after the diagnosis notify the defendant's attorney, partner, and family members of the defendant's condition and inform the defendant's attorney, partner, and family members that they may prepare and submit on the defendant's behalf a request for a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) not later than 7 days after the date of the diagnosis, provide the defendant's partner and family members (including extended family) with an opportunity to visit the defendant in person;"],[3,"(iii) upon request from the defendant or his attorney, partner, or a family member, ensure that Bureau of Prisons employees assist the defendant in the preparation, drafting, and submission of a request for a sentence reduction pursuant to subsection (c)(1)(A); and"],[3,"(iv) not later than 14 days of receipt of a request for a sentence reduction submitted on the defendant's behalf by the defendant or the defendant's attorney, partner, or family member, process the request;"],[2,"(B) in the case of a defendant who is physically or mentally unable to submit a request for a sentence reduction pursuant to subsection (c)(1)(A)—"],[3,"(i) inform the defendant's attorney, partner, and family members that they may prepare and submit on the defendant's behalf a request for a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) accept and process a request for sentence reduction that has been prepared and submitted on the defendant's behalf by the defendant's attorney, partner, or family member under clause (i); and"],[3,"(iii) upon request from the defendant or his attorney, partner, or family member, ensure that Bureau of Prisons employees assist the defendant in the preparation, drafting, and submission of a request for a sentence reduction pursuant to subsection (c)(1)(A); and"],[2,"(C) ensure that all Bureau of Prisons facilities regularly and visibly post, including in prisoner handbooks, staff training materials, and facility law libraries and medical and hospice facilities, and make available to prisoners upon demand, notice of—"],[3,"(i) a defendant's ability to request a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) the procedures and timelines for initiating and resolving requests described in clause (i); and"],[3,"(iii) the right to appeal a denial of a request described in clause (i) after all administrative rights to appeal within the Bureau of Prisons have been exhausted."],[1,"(3) Annual report.—Not later than 1 year after December 21, 2018, and once every year thereafter, the Director of the Bureau of Prisons shall submit to the Committee on the Judiciary of the Senate and the Committee on the Judiciary of the House of Representatives a report on requests for sentence reductions pursuant to subsection (c)(1)(A), which shall include a description of, for the previous year—"],[2,"(A) the number of prisoners granted and denied sentence reductions, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(B) the number of requests initiated by or on behalf of prisoners, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(C) the number of requests that Bureau of Prisons employees assisted prisoners in drafting, preparing, or submitting, categorized by the criteria relied on as the grounds for a reduction in sentence, and the final decision made in each request;"],[2,"(D) the number of requests that attorneys, partners, or family members submitted on a defendant's behalf, categorized by the criteria relied on as the grounds for a reduction in sentence, and the final decision made in each request;"],[2,"(E) the number of requests approved by the Director of the Bureau of Prisons, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(F) the number of requests denied by the Director of the Bureau of Prisons and the reasons given for each denial, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(G) for each request, the time elapsed between the date the request was received by the warden and the final decision, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(H) for each request, the number of prisoners who died while their request was pending and, for each, the amount of time that had elapsed between the date the request was received by the Bureau of Prisons, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(I) the number of Bureau of Prisons notifications to attorneys, partners, and family members of their right to visit a terminally ill defendant as required under paragraph (2)(A)(ii) and, for each, whether a visit occurred and how much time elapsed between the notification and the visit;"],[2,"(J) the number of visits to terminally ill prisoners that were denied by the Bureau of Prisons due to security or other concerns, and the reasons given for each denial; and"],[2,"(K) the number of motions filed by defendants with the court after all administrative rights to appeal a denial of a sentence reduction had been exhausted, the outcome of each motion, and the time that had elapsed between the date the request was first received by the Bureau of Prisons and the date the defendant filed the motion with the court."],[0,"(e) Inclusion of an Order To Limit Criminal Association of Organized Crime and Drug Offenders.—The court, in imposing a sentence to a term of imprisonment upon a defendant convicted of a felony set forth in chapter 95 (racketeering) or 96 (racketeer influenced and corrupt organizations) of this title or in the Comprehensive Drug Abuse Prevention and Control Act of 1970 (21 U.S.C. 801 et seq.), or at any time thereafter upon motion by the Director of the Bureau of Prisons or a United States attorney, may include as a part of the sentence an order that requires that the defendant not associate or communicate with a specified person, other than his attorney, upon a showing of probable cause to believe that association or communication with such person is for the purpose of enabling the defendant to control, manage, direct, finance, or otherwise participate in an illegal enterprise."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3582?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§3582. Imposition of a sentence of imprisonment","tname":"Crimes and Criminal Procedure","by":{"1":"29, 35, 29, 35, 29, 35, 29, 35, 29, 35"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(c)"],"by":{"1":"28, 35"}},{"t":"usc","label":"18 U.S.C. § 3771","url":"https://www.law.cornell.edu/uscode/text/18/3771","subs":["(a)(2)","(a)(4)"],"by":{"1":"34, 34"}},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","subs":["(h)"],"by":{"1":"11, 12, 18, 35, 38, 39, 12"}},{"t":"reg","label":"75 Fed. Reg. 66,188","url":"https://www.govinfo.gov/link/fr/75/66188","by":{"1":"8"}},{"t":"case","label":"Brown v. Gardner","cite":"513 U.S. 115","y":1994,"id":"1994/93-1128","sc":1,"sum":"The Court affirmed the lower court's decision and ruled for Gardner. The Court held that Section 1151 contains no language requiring proof of fault, and it rejected the Government's claims that the requirement was implicit in the language of the statute.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"EEOC v. Abercrombie & Fitch Stores, Inc.","cite":"575 U.S. 768","y":2015,"id":"2014/14-86","sc":1,"sum":"The Court held that an employer may be held liable under Title VII of the Civil Rights Act if an applicant can show that her need for an accommodation was a motivating factor in the employer’s decision not to hire her.","sumSrc":"Oyez","by":{"2":"9"}},{"t":"case","label":"Gonzales v. Duenas-Alvarez","cite":"549 U.S. 183","y":2007,"id":"2006/05-1629","sc":1,"sum":"The Court ruled unanimously that aiding and abetting a theft qualifies as a \"theft offense\" for purposes of the Immigration and Nationality Act. The opinion by Justice Stephen Breyer held that the common law had done away with all distinctions between \"principals\" and \"aiders and abettors\" of theft crimes.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Intel Corp. Inv. Pol’y Comm. v. Sulyma","cite":"140 S. Ct. 768","y":2020,"id":"2019/18-1116","sc":1,"sum":"The Court held that under the Employee Retirement Income Security Act of 1974 requirement that plaintiffs with “actual knowledge” of an alleged fiduciary breach must file suit within three years of gaining that knowledge, a plaintiff does not necessarily have “actual knowledge” of the information contained in disclosures that he receives but does not read or cannot recall reading.","sumSrc":"Oyez","by":{"2":"3"}},{"t":"case","label":"Moskal v. United States","cite":"498 U.S. 103","y":1990,"id":"1990/89-964","sc":1,"sum":"A person who receives genuine vehicle titles, knowing that they incorporate fraudulently tendered odometer readings, receives those titles knowing them to have been \"falsely made\" in violation of § 2314.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19"}},{"t":"case","label":"Rodriguez v. FDIC","cite":"140 S. Ct. 713","y":2020,"id":"2019/18-1269","sc":1,"sum":"A case in which the Court vacated the ruling below that had applied a federal common-law rule on how to allocate a tax refund paid to an affiliated group.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Travelers Cas. & Sur. Co. of Am. v. Pac. Gas & Elec. Co.","cite":"549 U.S. 443","y":2007,"id":"2006/05-1429","sc":1,"sum":"Justice Samuel Alito issued the unanimous opinion, which found that the Bankruptcy Code did not expressly waive the contractual obligation to reimburse attorney fees even if incurred in federal litigation.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"United States v. Briggs","cite":"141 S. Ct. 467","y":2020,"id":"2020/19-108","sc":1,"sum":"Respondents’ prosecutions for military rape were timely commenced under the Uniform Code of Military Justice’s statute of limitations.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"4"}},{"t":"case","label":"United States v. Broadway","cite":"1 F.4th 1206","y":2021,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/1/1206/","by":{"2":"9"}},{"t":"case","label":"United States v. Conhaim","cite":"160 F.3d 893","y":1998,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/160/893/","by":{"2":"7"}},{"t":"case","label":"United States v. Fleming","cite":"5 F.4th 189","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/5/189/","by":{"2":"7"}},{"t":"case","label":"United States v. Husein","cite":"478 F.3d 318","y":2007,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/478/318/","by":{"2":"6"}},{"t":"case","label":"United States v. Johnson","cite":"351 F. App’x 948","y":2009,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/351/948/","by":{"2":"7"}},{"t":"case","label":"United States v. Kozminski","cite":"487 U.S. 931","y":1988,"id":"1987/86-2000","sc":1,"sum":"The Court held that precedent had established that the type of involuntary servitude prohibited by the Thirteenth Amendment is limited to that “enforced by the use or threatened use of physical or legal coercion.” Involuntary servitude had never before been extended to cover labor compelled by the use of psychological coercion.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"United States v. R.L.C.","cite":"503 U.S. 291","y":1992,"id":"1991/90-1577","sc":1,"sum":"The judgment is affirmed. 915 F. 2d 320, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19"}},{"t":"case","label":"United States v. Saddler","cite":"538 F.3d 879","y":2008,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/538/879/","by":{"2":"6"}},{"t":"case","label":"United States v. Santos","cite":"553 U.S. 507","y":2008,"id":"2007/06-1005","sc":1,"sum":"Splitting 5 to 4, the Court affirmed the Seventh Circuit, answering that \"proceeds\" refers to \"net income\" or profits and not to \"gross income.\" Because the statute nowhere defines the term \"proceeds\", the plurality applied the so-called rule of lenity which requires such ambiguous statutes to be interpreted in favor of defendants.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"United States v. Smith","cite":"959 F.3d 701","y":2020,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/959/701/","by":{"2":"12"}},{"t":"case","label":"United States v. White","cite":"984 F.3d 76","y":2020,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/984/76/","op":1,"by":{"2":"12"}},{"t":"case","label":"United States v. Woodside","cite":"895 F.3d 894","y":2018,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/895/894/","by":{"2":"7"}},{"t":"rule","label":"Fed. R. Crim. P. 35","url":"https://www.law.cornell.edu/rules/frcrmp/rule_35","by":{"2":"16"}}]};